    "C01", "C02", "C03", "C07", "C10", "C12"
  ],
  "claims": [
    {
      "claim": "Visible steroid-like contexts report absolute oral bioavailability well above 20%: digitoxin 90.6–91.2%, β-methyldigoxin 59–76%, UDCA 78–87%, ethinylestradiol 76.9%, and danazol 46–67% in fed humans.",
      "card_ids": ["C09", "C15", "C08", "C18", "C20", "C14", "C04", "C05", "C06", "C13", "C17"]
    },
    {
      "claim": "Lipophilic, poorly soluble drugs with first-pass challenges still meet or approach the threshold in fasted humans: lefamulin 25.8% and tacrolimus about 20%.",
      "card_ids": ["C01", "C02", "C03", "C07", "C10"]
    },
    {
      "claim": "An active-metabolite context, perindoprilat after oral perindopril, reports systemic availability of 30 ± 6% in cirrhosis, supporting that active metabolites can meet the F ≥ 20% threshold.",
      "card_ids": ["C12"]
    },
    {
      "claim": "New L2 records for the same steroid contexts are consistent with high F (digitoxin 89.7%, danazol 44 ± 12% and 60%, ethinylestradiol 76.9%, β-methyldigoxin tablet/IV 0.92), reinforcing the high direction.",
      "card_ids": ["C31", "C23", "C28", "C29", "C30", "C25"]
    },
    {
      "claim": "The only low new values (tacrolimus rat ~10% and variable 5–67%) come from a macrolide in rats or across conditions and are not transferable to the corticosteroid-like query.",
      "card_ids": ["C21", "C24"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "associated_nonvoting_records",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C31", "C23", "C28", "C29", "C30", "C25", "C22"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C21", "C24"]
    },
    {
      "family": "associated_nonvoting_records",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C26", "C27", "C32"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule (a corticosteroid-like 16,17-acetal with a cyclohexyl substituent).",
    "No visible context is a corticosteroid; transfer from cardiac glycosides, bile acids, estrogens, and danazol is structural-class analogy.",
    "Prandial state is unspecified; food effects on this lipophilic acetal are unknown.",
    "Acid lability of the 1,3-dioxolane and hepatic first-pass metabolism of the corticosteroid side chain are not quantified in visible records.",
    "Tacrolimus rat low F is species-specific and not transferable, but highlights that lipophilic drugs can have low F in some conditions."
  ],
  "decision_summary": "Predicted high (F >= 20%) because all transferable steroid-like contexts report F at or above 20%, new L2 records reinforce those values, and the only low new values are non-transferable rat/macrolide data; confidence remains moderate due to lack of direct corticosteroid-acetal evidence and unspecified prandial state."
}

